/* One persistent audio element; changing pages never recreates the player. */
(()=>{
'use strict';
const C=window.IrisMusicCore;
const Cloud=window.IrisMusicCloud;
const lyricsRequests=new Map(),lyricsChoices=new Map(),resolvingRoleInvites=new Set(),expiredUrlRetries=new Set();
let rt=null,audio=null,mini=null,trackId='',tab='player',epoch=0,objectUrl='',importing=false,pending=false,selectedLyrics=-2,activeScope='',lastSaved=0,dialog=null,database=null,boundUserId='',requestSerial=0,loadedTrackId='';
let cloudToken='',cloudProfile=null,cloudBusy=false,cloudTimer=null;
const esc=v=>rt.esc(String(v??''));
const music=()=>C.normalize(rt.state);
const who=()=>rt.identity();
const owner=()=>who()?.userId||'';
const tracks=()=>C.library(rt.state,owner());
const current=()=>tracks().find(x=>x.id===trackId);
const together=()=>{const i=who();return i?.roleId&&i.userId?C.session(rt.state,i.userId,i.roleId):null};
const pref=()=>music().preferences[owner()]||=( {mode:'order',volume:1,positions:{}} );
const visible=()=>Boolean(rt?.isActive());
const same=(identity)=>{const now=who();return now?.userId===identity?.userId&&now?.roleId===identity?.roleId&&rt.valid(identity)};
function fail(error){rt.toast(error?.message||String(error)||'听歌操作失败')}
function persist(){rt.save()}
function openDatabase(){if(database)return database;database=new Promise((resolve,reject)=>{const request=indexedDB.open('iris-music-media',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('tracks'))request.result.createObjectStore('tracks')};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||Error('无法打开本地音频存储'));request.onblocked=()=>reject(Error('本地音频存储被其他页面占用'))});database.catch(()=>database=null);return database}
async function media(operation,id,value){const db=await openDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction('tracks',operation==='get'?'readonly':'readwrite'),store=tx.objectStore('tracks');let result;const request=operation==='get'?store.get(id):operation==='put'?store.put(value,id):store.delete(id);request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error||Error('本地音频存储失败，请检查可用空间'));tx.onabort=()=>reject(tx.error||Error('本地音频未能保存'))})}
function dataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败'));reader.readAsDataURL(blob)})}
function probe(src){return new Promise((resolve,reject)=>{const node=new Audio(),timer=setTimeout(()=>done(Error('音频加载超时，请检查文件或音频直链')),12000);function done(error){clearTimeout(timer);node.onloadedmetadata=null;node.onerror=null;node.removeAttribute('src');node.load();error?reject(error):resolve(duration)}let duration=0;node.preload='metadata';node.onloadedmetadata=()=>{duration=node.duration;if(!Number.isFinite(duration)||duration<=0){done(Error('当前来源不是可读取的歌曲音频'));return}done()};node.onerror=()=>done(Error('无法读取音频，请检查格式、直链权限或网络'));node.src=src;node.load()})}
function paintRange(input){if(!input)return;const min=Number(input.min)||0,max=Number(input.max)||1,value=Number(input.value)||0;input.style.setProperty('--music-progress',Math.max(0,Math.min(100,(value-min)/(max-min)*100))+'%')}
function filePicker(kind,title,accept,detail){const icon=kind==='cover'?'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 4-5 5 6"/>':'<path d="M6 3h8l4 4v14H6Z"/><path d="M14 3v5h4M9 12h6M9 16h4"/>';return `<div class="music-file-field"><div class="music-file-heading"><span>${title}</span>${kind==='cover'?'<button type="button" data-music-cover-remove>移除封面</button>':''}</div><label class="music-file-picker"><input type="file" accept="${accept}" data-music-${kind}-file aria-label="${title}"><svg viewBox="0 0 24 24" aria-hidden="true">${icon}</svg><span><strong>${kind==='cover'?'选择封面图片':'选择歌词文件'}</strong><small data-music-${kind}-name>${detail}</small></span><svg class="music-file-plus" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg></label></div>`}
function format(seconds){const value=Math.max(0,Math.floor(Number(seconds)||0));return Math.floor(value/60)+':'+String(value%60).padStart(2,'0')}
function cover(t,cls=''){return t?.cover?`<img class="${cls}" src="${esc(t.cover)}" alt="歌曲封面">`:`<span class="music-cover-placeholder ${cls}" aria-hidden="true"><svg viewBox="0 0 48 48"><circle cx="24" cy="24" r="18"/><circle cx="24" cy="24" r="6"/><circle cx="24" cy="24" r="2"/></svg></span>`}
function savePosition(){if(!rt||!audio||loadedTrackId!==trackId||!boundUserId||!C.library(rt.state,boundUserId).some(x=>x.id===trackId))return;const saved=music().preferences[boundUserId]||={positions:{}};saved.positions||={};saved.positions[trackId]=Math.max(0,audio.currentTime||0);persist()}
function mediaSession(){if(!('mediaSession'in navigator)||!current())return;try{const t=current();navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist||'',album:'Iris · 一起听',...(t.cover?{artwork:[{src:t.cover}]}:{})});navigator.mediaSession.playbackState=audio.paused?'paused':'playing';for(const [name,handler] of Object.entries({play:()=>play(),pause:()=>audio.pause(),stop:()=>audio.pause(),previoustrack:()=>step(-1),nexttrack:()=>step(1),seekto:event=>{if(Number.isFinite(event.seekTime))audio.currentTime=event.seekTime}}))navigator.mediaSession.setActionHandler(name,handler)}catch{}}
function initAudio(){if(audio)return;audio=document.createElement('audio');audio.preload='metadata';audio.setAttribute('playsinline','');audio.hidden=true;document.body.append(audio);
 audio.addEventListener('loadedmetadata',()=>{const t=current();if(!t||!audio.getAttribute('src'))return;loadedTrackId=t.id;if(Number.isFinite(audio.duration))t.duration=audio.duration;const position=Number(pref().positions?.[trackId])||0;if(position>0&&position<audio.duration)audio.currentTime=position;persist();updatePlayback()});
 for(const event of ['play','pause'])audio.addEventListener(event,()=>{if(!audio.paused&&!sameScope())audio.pause();if(event==='pause')savePosition();mediaSession();updatePlayback()});
 audio.addEventListener('timeupdate',()=>{updatePlayback();if(Date.now()-lastSaved>10000){lastSaved=Date.now();savePosition()}});
 audio.addEventListener('error',()=>{const item=current();if(item&&audio.getAttribute('src')){if(item.platform==='netease'&&item.platformId&&Cloud&&cloudToken){const key=item.platformId+'|'+item.url;if(!expiredUrlRetries.has(key)){expiredUrlRetries.add(key);void refreshExpiredUrl(item,key);return}}fail(Error('歌曲播放失败，请检查文件、链接或网络'));updatePlayback()}});
 audio.addEventListener('ended',()=>{if(!current())return;pref().positions[trackId]=0;persist();if(pref().mode==='repeat-one'){audio.currentTime=0;void play()}else void step(1,true)});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)savePosition();else sync()});window.addEventListener('pagehide',savePosition);
}
async function refreshExpiredUrl(item,key){try{const result=await Cloud.song(item.platformId,cloudToken),song=result?.song;if(!song?.playUrl||song.playUrl===item.url)throw Error('网易云没有提供新的播放地址');item.url=song.playUrl;item.title=song.name||item.title;item.artist=song.artist||item.artist;item.album=song.album||item.album;item.cover=song.cover||item.cover;item.lyrics=song.lyrics||item.lyrics;persist();await load(item,true)}catch(error){fail(Error(error?.message||'歌曲播放失败，请检查文件、链接或网络'));updatePlayback()}}
function sameScope(){return activeScope===[who()?.userId||'',who()?.roleId||''].join(':')}
async function load(t,autoplay=false){initAudio();savePosition();loadedTrackId='';const version=++epoch,identity={...who()};audio.pause();audio.removeAttribute('src');audio.load();if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=''}trackId=t.id;selectedLyrics=-2;pref().miniClosed=false;pref().trackId=t.id;persist();
 const s=together();if(s?.active&&s.runs.find(x=>x.id===s.currentRunId)?.trackId!==t.id)C.begin(s,t);
 if(visible())renderPage();syncMini();try{let src=t.url;if(t.kind==='local'){const blob=await media('get',t.mediaId);if(!(blob instanceof Blob))throw Error('本地音频文件不存在，请重新导入这首歌');if(version!==epoch||!same(identity))return;src=URL.createObjectURL(blob);objectUrl=src}if(version!==epoch||!same(identity))return;audio.src=src;audio.volume=Math.max(0,Math.min(1,Number.isFinite(Number(pref().volume))?Number(pref().volume):1));audio.load();if(autoplay)await play()}catch(error){if(version===epoch)fail(error)}}
async function play(){if(rt)pref().miniClosed=false;if(!current()||!audio?.getAttribute('src'))return;if(!sameScope())return;try{await audio.play()}catch(error){fail(Error(error.name==='NotAllowedError'?'浏览器阻止了播放，请再次点击播放按键':'当前音频无法播放，请检查文件或链接'))}updatePlayback()}
async function step(direction,automatic=false){const t=C.next(tracks(),trackId,pref().mode,direction);if(t)await load(t,true);else if(automatic){audio.pause();updatePlayback()}}
function dismissMini(){
 if(!rt)return;++epoch;++requestSerial;pending=false;savePosition();pref().miniClosed=true;
 const s=together();if(s?.active)C.end(s);audio?.pause();loadedTrackId='';audio?.removeAttribute('src');audio?.load();if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=''}trackId='';
 if(mini)mini.hidden=true;try{if(navigator.mediaSession){navigator.mediaSession.metadata=null;navigator.mediaSession.playbackState='none';for(const action of ['play','pause','stop','previoustrack','nexttrack','seekto'])navigator.mediaSession.setActionHandler(action,null)}}catch{}persist();
}
function syncMini(){if(!rt)return;if(!mini){mini=document.createElement('aside');mini.className='music-mini-player';mini.setAttribute('aria-label','一起听播放器');document.querySelector('.phone')?.insertBefore(mini,document.querySelector('.bottom'));mini.onclick=event=>{const button=event.target.closest('button');if(!button)return;if(button.hasAttribute('data-music-mini-close')){event.stopPropagation?.();dismissMini()}else if(button.hasAttribute('data-music-mini-play'))audio?.paused?void play():audio?.pause();else rt.open()}}
 const t=current(),i=who();mini.hidden=!t||pref().miniClosed===true||!sameScope()||!rt.isChatVisible();if(mini.hidden)return;const signature=[t.id,i.userId,i.roleId,t.title,t.artist,t.cover,together()?.active].join('|');if(mini._musicSignature===signature){const button=mini.querySelector('[data-music-mini-play]');if(button){button.textContent=audio?.paused?'▷':'Ⅱ';button.setAttribute('aria-label',audio?.paused?'播放':'暂停')}return}mini._musicSignature=signature;mini.innerHTML=`<button type="button" data-music-mini-open>${cover(t)}<span><strong>${esc(t.title)}</strong><small>${together()?.active?esc(i.roleName)+' · 一起听':esc(t.artist||'音乐')}</small></span></button><button type="button" data-music-mini-play aria-label="${audio?.paused?'播放':'暂停'}">${audio?.paused?'▷':'Ⅱ'}</button><button type="button" data-music-mini-close aria-label="关闭音乐"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m6 6 8 8M14 6l-8 8"/></svg></button>`}
function updatePlayback(){syncMini();if(!visible())return;const box=rt.content,t=current();if(!t)return;const duration=Number.isFinite(audio?.duration)?audio.duration:t.duration||0,time=audio?.currentTime||0;box.querySelectorAll('[data-music-play]').forEach(x=>{x.textContent=audio?.paused?'▷':'Ⅱ';x.setAttribute('aria-label',audio?.paused?'播放':'暂停');x.disabled=!audio?.getAttribute('src')});const range=box.querySelector('[data-music-seek]');if(range&&document.activeElement!==range){range.max=String(duration||1);range.value=String(time)}paintRange(range);const currentTime=box.querySelector('[data-music-time]'),end=box.querySelector('[data-music-duration]');if(currentTime)currentTime.textContent=format(time);if(end)end.textContent=format(duration);const rows=C.lyrics(t.lyrics),index=rows.findLastIndex(x=>x.at<=time);if(index!==selectedLyrics){selectedLyrics=index;box.querySelectorAll('[data-music-lyric]').forEach(x=>x.classList.toggle('active',Number(x.dataset.musicLyric)===index));const active=box.querySelector('[data-music-lyric].active'),lyrics=box.querySelector('.music-lyrics');if(active&&lyrics)lyrics.scrollTop=Math.max(0,active.offsetTop-lyrics.clientHeight/2+active.clientHeight/2)}}
function cloudState(){const m=music();m.netEaseByUser||={};const data=m.netEaseByUser[owner()]||=( {playlists:[],favorites:[],songs:{},playlistDetails:{}} );data.songs||={};data.playlistDetails||={};return data}
function cloudError(error){fail(Error(error?.message||'网易云服务暂时不可用'))}
function resolveRoleInvites(){if(!rt||!Cloud||!rt.isChatVisible?.())return;const thread=rt.chatMessages?.(),identity={...who()};if(!Array.isArray(thread))return;for(const message of thread){if(message?.type!=='music-invite'||message.musicInviteStatus!=='resolving'||resolvingRoleInvites.has(message.id))continue;if(message._musicRoleIndex!==identity.roleIndex||message._musicUserIndex!==identity.userIndex)continue;resolvingRoleInvites.add(message.id);void Cloud.resolve(message.musicTitle,message.musicArtist).then(result=>{if(!same(identity)||!thread.includes(message)||message.musicInviteStatus!=='resolving')return;const song=result?.song;if(!song?.id||!song?.playUrl)throw Error('没有找到可播放的匹配版本');message.musicSong=song;message.musicInviteStatus='pending';delete message._musicRoleIndex;delete message._musicUserIndex;music().roleInviteAt||={};music().roleInviteAt[`${identity.roleId}-${identity.userId}`]=Date.now();C.rememberRoleSong(rt.state,identity.roleId,song,'role-invitation');cloudState().songs[String(song.id)]=song;rt.save();rt.refreshChat?.()}).catch(error=>{if(!same(identity)||!thread.includes(message))return;const index=thread.indexOf(message);if(index>=0)thread.splice(index,1);rt.save();rt.refreshChat?.();cloudError(error)}).finally(()=>resolvingRoleInvites.delete(message.id))}}
async function restoreCloud(){if(!Cloud||!owner())return;try{cloudToken=await Cloud.getToken(owner())||'';if(cloudToken){const result=await Cloud.me(cloudToken);cloudProfile=result.user||null;cloudState().user=cloudProfile;persist()}else cloudProfile=null}catch(error){if(/登录已失效|尚未登录/.test(error.message||'')){await Cloud.logout(owner(),cloudToken);cloudToken='';cloudProfile=null;delete cloudState().user;persist()}else if(visible())cloudError(error)}if(visible())renderPage()}
function cloudLogin(){const identity={...who()};let stopped=false,qrId='',polling=false;const node=openDialog('NetEase Account',`<section class="music-net-login"><p class="music-net-intro">使用网易云音乐 App 扫码登录</p><div class="music-net-qr" data-net-qr><span>正在生成二维码…</span></div><p class="music-net-state" data-net-state>请稍候</p><button type="button" class="music-action-primary" data-net-refresh>刷新二维码</button><small>登录凭证由 Iris 音乐服务加密保管，可随时退出。</small></section>`),qr=node.querySelector('[data-net-qr]'),state=node.querySelector('[data-net-state]'),refresh=node.querySelector('[data-net-refresh]');
 const stop=()=>{stopped=true;clearTimeout(cloudTimer)};node.addEventListener('close',stop);
 const start=async()=>{clearTimeout(cloudTimer);qrId='';refresh.disabled=true;qr.innerHTML='<span>正在生成二维码…</span>';state.textContent='请稍候';try{const result=await Cloud.startQr();if(stopped||!node.open||!same(identity))return;qrId=result.id;if(result.qrImage)qr.innerHTML=`<img src="${esc(result.qrImage.startsWith('data:')?result.qrImage:'data:image/png;base64,'+result.qrImage)}" alt="网易云扫码登录二维码">`;else qr.innerHTML=`<a href="${esc(result.qrUrl)}" target="_blank" rel="noopener noreferrer">打开网易云登录页</a>`;state.textContent='等待扫码';refresh.disabled=false;void poll()}catch(error){if(!stopped){state.textContent=error.message||'二维码加载失败';qr.innerHTML='';refresh.disabled=false}}};
 const poll=async()=>{if(stopped||polling||!qrId)return;polling=true;try{const result=await Cloud.pollQr(qrId);if(stopped||!node.open||!same(identity))return;if(result.status==='authorized'&&result.token){cloudToken=result.token;cloudProfile=result.user||null;await Cloud.saveToken(owner(),cloudToken);cloudState().user=cloudProfile;cloudState().playlists=[];cloudState().syncedAt=0;persist();state.textContent='登录成功';qr.innerHTML='<span class="music-net-success">网易云账号已连接</span>';setTimeout(()=>{if(node.open)node.close();if(visible())renderPage()},550);return}state.textContent=result.status==='scanned'?'已扫码，请在网易云音乐中确认':result.status==='expired'?'二维码已过期，请刷新':'等待扫码';if(result.status==='expired'){refresh.disabled=false;return}}catch(error){if(!stopped)state.textContent=error.message||'正在重试'}finally{polling=false;if(!stopped&&node.open&&qrId)cloudTimer=setTimeout(poll,1800)}};
 refresh.onclick=()=>void start();void start()}
async function syncCloudPlaylists(button){if(!cloudToken){cloudLogin();return}button.disabled=true;button.textContent='正在同步…';try{const result=await Cloud.playlists(cloudToken);if(!sameScope())return;const saved=cloudState();saved.playlists=Array.isArray(result.playlists)?result.playlists:[];saved.syncedAt=Date.now();persist();renderPage()}catch(error){cloudError(error)}finally{button.disabled=false;button.textContent='同步歌单'}}
function cloudProfilePage(){
 const data=cloudState(),lists=data.playlists||[],favorites=music().favoritePlaylists.filter(item=>item.userId===owner()),tracks=data.favorites||[];
 const playlistRows=lists.map(item=>`<button type="button" data-net-playlist="${esc(item.id)}">${cover({cover:item.cover})}<span><strong>${esc(item.name)}</strong><small>${item.trackCount} 首 · ${esc(item.creator||'网易云歌单')}</small></span><i>›</i></button>`).join('');
 const savedLists=favorites.map(item=>`<button type="button" data-net-favorite-playlist="${esc(item.id)}">${cover({cover:item.cover})}<span><strong>${esc(item.name)}</strong><small>${item.trackCount} 首 · 已收藏</small></span><i>›</i></button>`).join('');
 const savedTracks=tracks.map(item=>`<button type="button" data-net-favorite-song="${esc(item.platformId||item.id)}">${cover({cover:item.cover})}<span><strong>${esc(item.title)}</strong><small>${esc(item.artist||'未知歌手')}</small></span><i>›</i></button>`).join('');
 const account=cloudToken?`<div class="music-net-library-heading"><strong>我的歌单</strong><button type="button" data-net-sync>同步歌单</button></div>${data.syncedAt?`<small class="music-net-sync-time">最近同步 · ${esc(new Date(data.syncedAt).toLocaleString('zh-CN'))}</small>`:''}<div class="music-net-playlists">${playlistRows||`<div class="music-empty"><strong>${cloudBusy?'正在读取歌单':'同步你的网易云歌单'}</strong><p>歌单资料会保存在当前设备的 Iris 音乐库中。</p>${cloudBusy?'':'<button type="button" data-net-sync>同步歌单</button>'}</div>`}</div>${favorites.length?`<div class="music-net-library-heading"><strong>已收藏的歌单</strong></div><div class="music-net-playlists">${savedLists}</div>`:''}${tracks.length?`<div class="music-net-library-heading"><strong>收藏单曲</strong></div><div class="music-net-playlists">${savedTracks}</div>`:''}`:`<div class="music-net-empty"><strong>连接你的网易云账号</strong><p>扫码后可在 Iris 查看网易云歌单，并收藏单曲或角色歌单。</p><button type="button" data-net-login class="music-action-primary">扫码登录网易云</button></div>`;
 return `<section class="music-net-page"><header class="music-net-profile">${cloudProfile?.avatar?`<img src="${esc(cloudProfile.avatar)}" alt="">`:'<span class="music-net-avatar">♫</span>'}<div><strong>${esc(cloudProfile?.nickname||'网易云音乐')}</strong><small>${cloudToken?'已连接网易云账号':'尚未登录'}</small></div>${cloudToken?'<button type="button" data-net-logout>退出</button>':'<button type="button" data-net-login>扫码登录</button>'}</header>${account}</section>`;
}
function roleRecentPage(){const i=who(),items=C.roleRecent(rt.state,i?.roleId||'');return `<section class="music-net-page"><header class="music-role-heading">${rt.avatarRole||''}<div><strong>${esc(i?.roleName||'角色')}</strong><small>最近在听</small></div>${items.length?'<button type="button" data-role-favorite-playlist>收藏近期歌单</button>':''}</header>${items.length?`<div class="music-net-playlists">${items.map(item=>`<article><button type="button" data-role-song="${esc(item.platformId)}">${cover({cover:item.cover})}<span><strong>${esc(item.title)}</strong><small>${esc(item.artist||'未知歌手')} · ${esc(new Date(item.updatedAt).toLocaleDateString('zh-CN'))}</small></span><i>▷</i></button><button type="button" data-role-favorite="${esc(item.platformId)}" aria-label="收藏歌曲">收藏</button></article>`).join('')}</div>`:'<div class="music-empty"><strong>角色分享的歌曲会显示在这里</strong><p>角色在聊天中分享歌曲或邀请一起听后，这里会留下最近听歌记录。</p></div>'}</section>`}
async function openCloudPlaylist(playlistId){const cached=cloudState().playlists.find(item=>item.id===playlistId),favorite=music().favoritePlaylists.find(item=>item.id===playlistId&&item.userId===owner());let data=favorite?{playlist:favorite}:cloudState().playlistDetails[playlistId]?{playlist:cloudState().playlistDetails[playlistId]}:null;if(!data){const node=openDialog('Playlist',`<p>正在读取歌单…</p>`);try{data=await Cloud.playlist(playlistId,cloudToken);if(!node.open)return;cloudState().playlistDetails[playlistId]=data.playlist;persist();node.querySelector('.music-dialog-body').innerHTML=playlistMarkup(data.playlist,cached,false);bindPlaylistDialog(node,data.playlist,cached,false)}catch(error){node.querySelector('.music-dialog-body').innerHTML=`<p role="alert">${esc(error.message)}</p>`}return}const node=openDialog('Playlist',playlistMarkup(data.playlist,cached,true));bindPlaylistDialog(node,data.playlist,cached,true)}
function playlistMarkup(playlist,summary,saved){const songs=playlist.tracks||[];return `<section class="music-cloud-playlist"><div class="music-cloud-playlist-head">${cover({cover:playlist.cover})}<div><strong>${esc(playlist.name||summary?.name||'歌单')}</strong><small>${Number(playlist.trackCount)||songs.length} 首歌曲</small></div></div><div class="music-cloud-playlist-actions">${saved?'<span>已收藏</span>':`<button type="button" data-net-save-playlist>收藏歌单</button>`}</div><div class="music-net-song-list">${songs.map(song=>`<article><button type="button" data-net-song="${esc(song.id)}">${cover({cover:song.cover||playlist.cover})}<span><strong>${esc(song.name)}</strong><small>${esc(song.artist||'未知歌手')}${song.album?' · '+esc(song.album):''}</small></span><i>▷</i></button><button type="button" data-net-song-favorite="${esc(song.id)}" aria-label="收藏歌曲">＋</button></article>`).join('')}</div></section>`}
function bindPlaylistDialog(node,playlist,summary,saved){node.querySelector('[data-net-save-playlist]')?.addEventListener('click',()=>{C.favoritePlaylist(rt.state,owner(),playlist);persist();node.querySelector('[data-net-save-playlist]').outerHTML='<span>已收藏到我的音乐</span>'});node.querySelectorAll('[data-net-song],[data-net-song-favorite]').forEach(button=>button.onclick=()=>void fetchCloudSong(button.dataset.netSong||button.dataset.netSongFavorite,{play:button.hasAttribute('data-net-song'),node}));}
async function fetchCloudSong(id,{play=false,node=null,roleId='',favorite=false}={}){try{const cachedRole=C.roleRecent(rt.state,who()?.roleId||'').find(item=>item.platformId===String(id)),savedRole=cachedRole?{id:cachedRole.platformId,name:cachedRole.title,artist:cachedRole.artist,album:cachedRole.album,cover:cachedRole.cover,playUrl:cachedRole.playUrl,lyrics:cachedRole.lyrics,duration:cachedRole.duration,lyricSource:cachedRole.lyricsSource?.name}:null;let song=cloudState().songs?.[id]||savedRole;if(!song){song=(await Cloud.song(id,cloudToken||'')).song;if(!song)throw Error('没有找到歌曲');cloudState().songs||={};cloudState().songs[id]=song;persist()}if(roleId)C.rememberRoleSong(rt.state,roleId,song,'role-share');if(favorite||!play){const already=tracks().find(item=>item.platform==='netease'&&item.platformId===String(id));if(!already){if(!song.playUrl)throw Error('歌曲资料已找到，但当前来源没有可播放的音频');const added=C.add(rt.state,owner(),{kind:'url',url:song.playUrl,title:song.name,artist:song.artist,album:song.album,cover:song.cover,lyrics:song.lyrics,lyricsSource:song.lyrics?{name:song.lyricSource||'网易云音乐',url:'https://music.163.com'}:null,duration:song.duration,platform:'netease',platformId:String(id)});cloudState().favorites.unshift({id:added.id,title:added.title,artist:added.artist,cover:added.cover,platformId:String(id)});if(!pref().trackId)pref().trackId=added.id;persist()}if(node?.open){node.querySelector('[data-net-song-favorite="'+CSS.escape(String(id))+'"]')?.replaceWith(Object.assign(document.createElement('span'),{textContent:'已收藏'}))}if(play){const added=tracks().find(item=>item.platformId===String(id));tab='player';await load(added,true);node?.close()}else if(visible())renderPage();return}if(play){if(!song.playUrl)throw Error('当前歌曲没有可播放来源');let added=tracks().find(item=>item.platform==='netease'&&item.platformId===String(id));if(!added)added=C.add(rt.state,owner(),{kind:'url',url:song.playUrl,title:song.name,artist:song.artist,album:song.album,cover:song.cover,lyrics:song.lyrics,duration:song.duration,platform:'netease',platformId:String(id)});persist();tab='player';await load(added,true);node?.close()}}catch(error){cloudError(error)}}
function renderPage(){if(!rt||!visible())return;const i=who(),t=current(),s=together(),list=tracks(),rows=t?C.lyrics(t.lyrics):[];const draft=rt.content.querySelector('[data-music-message]')?.value||'';
 rt.content.innerHTML=`<section class="music-page"><nav class="music-tabs" aria-label="一起听页面"><button type="button" data-music-tab="player" class="${tab==='player'?'active':''}">正在听</button><button type="button" data-music-tab="library" class="${tab==='library'?'active':''}">曲库 <small>${list.length}</small></button><button type="button" data-music-tab="role" class="${tab==='role'?'active':''}">角色最近</button><button type="button" data-music-tab="cloud" class="${tab==='cloud'?'active':''}">我的</button><button type="button" data-music-history>共同记录</button></nav><div class="music-page-body">${tab==='library'?`<div class="music-library-actions"><button type="button" data-music-import ${importing?'disabled':''}>${importing?'正在导入…':'导入本地歌曲'}</button><button type="button" data-music-link>添加音频链接</button><input type="file" accept="audio/*,.mp3,.m4a,.aac,.wav,.ogg,.flac,.opus,.webm" multiple data-music-files hidden></div><div class="music-track-list">${list.length?list.map((item,index)=>`<article class="${item.id===trackId?'active':''}"><button type="button" data-music-select="${esc(item.id)}">${cover(item)}<span><strong>${esc(item.title)}</strong><small>${esc(item.artist||'未填写歌手')} · ${item.kind==='local'?'本地歌曲':'音频链接'}</small></span><small>${format(item.duration)}</small></button><button type="button" data-music-edit="${esc(item.id)}" aria-label="编辑${esc(item.title)}">···</button></article>`).join(''):'<div class="music-empty"><strong>留一首想一起听的歌</strong><p>导入本地音频，或添加可以播放的音频直链。</p></div>'}</div>`:tab==='cloud'?cloudProfilePage():tab==='role'?roleRecentPage():`<div class="music-companions"><span>${rt.avatarUser||''}<small>${esc(i?.userName||'用户')}</small></span><i>with</i><span>${rt.avatarRole||''}<small>${esc(i?.roleName||'尚未绑定角色')}</small></span></div>${t?`<div class="music-artwork">${cover(t)}</div><div class="music-song-title"><h2>${esc(t.title)}</h2><p>${esc(t.artist||'未填写歌手')}</p><button type="button" data-music-edit="${esc(t.id)}">编辑歌曲与歌词</button>${!t.lyrics?`<button type="button" data-music-find-lyrics ${lyricsRequests.has(t.id)?'disabled':''}>${lyricsRequests.has(t.id)?'正在查找歌词…':t.lyricsLookup?.status==='choose'?'选择歌词版本':'联网查找歌词'}</button>`:''}</div><div class="music-timeline"><input type="range" data-music-seek min="0" max="${t.duration||1}" step="0.1" value="0" aria-label="播放进度"><div><time data-music-time>0:00</time><time data-music-duration>${format(t.duration)}</time></div></div><div class="music-player-controls"><button type="button" data-music-prev aria-label="上一首">|◁</button><button type="button" data-music-play aria-label="播放">▷</button><button type="button" data-music-next aria-label="下一首">▷|</button></div><div class="music-player-options"><select data-music-mode aria-label="播放顺序">${[['order','顺序播放'],['repeat-one','单曲循环'],['shuffle','随机播放']].map(([value,label])=>`<option value="${value}" ${pref().mode===value?'selected':''}>${label}</option>`).join('')}</select><label>音量<input type="range" data-music-volume min="0" max="1" step="0.05" value="${pref().volume??1}" aria-label="音量"></label></div>${t.lyrics?`<div class="music-lyrics" aria-label="歌曲歌词">${rows.length?rows.map((row,index)=>`<button type="button" data-music-lyric="${index}" data-music-lyric-time="${row.at}">${esc(row.text)||'·'}</button>`).join(''):`<p>${esc(t.lyrics)}</p>`}</div>`:''}${t.lyricsSource?.name?`<small class="music-lyrics-source">歌词来源 · <a href="${t.lyricsSource.name==='Lyrics.ovh'?'https://lyrics.ovh':'https://lrclib.net'}" target="_blank" rel="noopener noreferrer" aria-label="歌词来源">${esc(t.lyricsSource.name)}</a></small>`:''}<div class="music-invite-row"><button type="button" data-music-invite ${(pending&&!s?.active)||!i?.roleId?'disabled':''}><span>${s?.active?'结束一起听':pending?'等待回应…':'邀请 '+esc(i?.roleName||'角色')+' 一起听'}</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="${s?.active?'M6 6l8 8M14 6l-8 8':'M4 10h12m-5-5 5 5-5 5'}"/></svg></button></div><section class="music-discussion"><header><span>一起听的聊天</span><button type="button" data-music-ask ${pending||!s?.active?'disabled':''}>问问 TA</button></header><div class="music-messages">${(s?.thread||[]).slice(-60).map(m=>`<article class="${m.mine?'mine':''}"><small>${esc(m.mine?i.userName:i.roleName)} · ${format(m.position)}</small><p>${esc(m.text)}</p>${m.suggestion&&!m.suggestion.resolved?`<div class="music-suggestion"><span>${m.suggestion.type==='repeat'?'想再听一遍':m.suggestion.type==='next'?'想换下一首':'想听 '+esc(list.find(x=>x.id===m.suggestion.trackId)?.title||'另一首歌')}</span><button type="button" data-music-suggestion="${esc(m.id)}" ${pending?'disabled':''}>同意</button><button type="button" data-music-dismiss="${esc(m.id)}">暂不</button></div>`:''}</article>`).join('')}</div><form data-music-chat><textarea rows="2" maxlength="3000" data-music-message placeholder="和 TA 说点什么…" aria-label="一起听消息">${esc(draft)}</textarea><button type="submit" ${pending||!s?.active?'disabled':''}>发送</button></form>${s?.failedRequest?.trackId===t.id?'<button type="button" class="music-retry" data-music-retry>重试回应</button>':''}</section>`:`<div class="music-empty"><strong>从一首歌开始</strong><p>先在曲库导入歌曲，再邀请 TA 一起听。</p><button type="button" data-music-tab="library">打开曲库</button></div>`}`}</div></section>`;
 bindPage();selectedLyrics=-2;updatePlayback();const messages=rt.content.querySelector('.music-messages');if(messages)messages.scrollTop=messages.scrollHeight;
}
function bindPage(){const box=rt.content;box.querySelector('[data-role-favorite-playlist]')?.addEventListener('click',()=>{const identity=who(),items=C.roleRecent(rt.state,identity?.roleId||'');if(!items.length)return;C.favoritePlaylist(rt.state,owner(),{id:identity.roleId,platform:'iris-role',name:identity.roleName+' · 最近在听',cover:items[0].cover,trackCount:items.length,tracks:items.map(item=>({id:item.platformId,name:item.title,artist:item.artist,album:item.album,cover:item.cover,playUrl:item.playUrl,lyrics:item.lyrics,duration:item.duration}))});persist();tab='cloud';renderPage()});box.querySelectorAll('input[type="range"]').forEach(input=>{paintRange(input);input.addEventListener('input',()=>paintRange(input))});
 box.querySelectorAll('[data-music-tab]').forEach(button=>button.onclick=()=>{tab=button.dataset.musicTab;renderPage()});box.querySelector('[data-music-import]')?.addEventListener('click',()=>box.querySelector('[data-music-files]').click());box.querySelector('[data-music-files]')?.addEventListener('change',event=>void importFiles([...event.target.files]));
 box.querySelectorAll('[data-net-login]').forEach(button=>button.onclick=cloudLogin);box.querySelectorAll('[data-net-sync]').forEach(button=>button.onclick=()=>void syncCloudPlaylists(button));box.querySelectorAll('[data-net-playlist]').forEach(button=>button.onclick=()=>void openCloudPlaylist(button.dataset.netPlaylist));box.querySelectorAll('[data-net-favorite-playlist]').forEach(button=>button.onclick=()=>void openCloudPlaylist(button.dataset.netFavoritePlaylist));box.querySelector('[data-net-logout]')?.addEventListener('click',async()=>{try{await Cloud.logout(owner(),cloudToken);cloudToken='';cloudProfile=null;delete cloudState().user;persist();renderPage()}catch(error){cloudError(error)}});box.querySelectorAll('[data-net-favorite-song]').forEach(button=>button.onclick=()=>void fetchCloudSong(button.dataset.netFavoriteSong,{play:true}));box.querySelectorAll('[data-role-song]').forEach(button=>button.onclick=()=>void fetchCloudSong(button.dataset.roleSong,{play:true}));box.querySelectorAll('[data-role-favorite]').forEach(button=>button.onclick=()=>void fetchCloudSong(button.dataset.roleFavorite,{favorite:true}));
 box.querySelector('[data-music-link]')?.addEventListener('click',linkDialog);box.querySelector('[data-music-find-lyrics]')?.addEventListener('click',()=>{const t=current();if(t)lyricsDialog(t)});box.querySelectorAll('[data-music-select]').forEach(button=>button.onclick=()=>{tab='player';void load(C.track(rt.state,owner(),button.dataset.musicSelect),true)});box.querySelectorAll('[data-music-edit]').forEach(button=>button.onclick=()=>editDialog(C.track(rt.state,owner(),button.dataset.musicEdit)));
 box.querySelector('[data-music-play]')?.addEventListener('click',()=>audio?.paused?void play():audio?.pause());box.querySelector('[data-music-prev]')?.addEventListener('click',()=>void step(-1));box.querySelector('[data-music-next]')?.addEventListener('click',()=>void step(1));box.querySelector('[data-music-seek]')?.addEventListener('change',event=>{if(audio&&Number.isFinite(audio.duration))audio.currentTime=Math.min(audio.duration,Math.max(0,Number(event.target.value)));savePosition()});
 box.querySelector('[data-music-mode]')?.addEventListener('change',event=>{pref().mode=event.target.value;persist()});box.querySelector('[data-music-volume]')?.addEventListener('input',event=>{audio.volume=Number(event.target.value);pref().volume=audio.volume;persist()});box.querySelectorAll('[data-music-lyric-time]').forEach(button=>button.onclick=()=>{if(Number.isFinite(audio.duration))audio.currentTime=Math.min(audio.duration,Number(button.dataset.musicLyricTime))});
 box.querySelector('[data-music-invite]')?.addEventListener('click',()=>together()?.active?endDialog():void respond('invite'));box.querySelector('[data-music-ask]')?.addEventListener('click',()=>void respond('ask'));box.querySelector('[data-music-chat]')?.addEventListener('submit',event=>{event.preventDefault();const field=box.querySelector('[data-music-message]'),value=field.value.trim();if(!value||pending||!together()?.active)return;field.value='';void respond('chat',value)});box.querySelector('[data-music-history]')?.addEventListener('click',historyDialog);box.querySelector('[data-music-retry]')?.addEventListener('click',()=>{const failed=together()?.failedRequest;if(failed?.trackId===trackId)void respond(failed.action)});
 box.querySelectorAll('[data-music-suggestion]').forEach(button=>button.onclick=()=>void acceptSuggestion(button.dataset.musicSuggestion));box.querySelectorAll('[data-music-dismiss]').forEach(button=>button.onclick=()=>{const m=together()?.thread.find(x=>x.id===button.dataset.musicDismiss);if(m?.suggestion)m.suggestion.resolved=true;persist();renderPage()});
}
async function importFiles(files){if(importing||!files.length)return;const identity={...who()},userId=identity.userId;if(!userId){fail(Error('请先选择用户'));return}importing=true;renderPage();const errors=[];
 try{for(const file of files){if(!same(identity))break;if(file.size>80*1024*1024){errors.push(file.name+'：音频不能超过80MB');continue}if(!/\.(mp3|m4a|aac|wav|ogg|oga|flac|opus|webm|mp4)$/i.test(file.name)&&!file.type.startsWith('audio/')){errors.push(file.name+'：不是支持的音频文件');continue}
 const fingerprint=[file.name,file.size,file.lastModified].join(':');const existing=C.library(rt.state,userId).find(x=>x.fingerprint===fingerprint);let temp='',mediaId='';try{if(existing&&(await media('get',existing.mediaId)) instanceof Blob)continue;temp=URL.createObjectURL(file);const duration=await probe(temp),meta=C.metadata(await file.slice(0,2*1024*1024).arrayBuffer()),picture=meta.picture?await dataUrl(new Blob([meta.picture.bytes],{type:meta.picture.type})):'';if(!same(identity))break;mediaId=existing?.mediaId||C.id();await media('put',mediaId,file);if(!same(identity)){await media('delete',mediaId);break}const t=existing||C.add(rt.state,userId,{kind:'local',mediaId,duration,title:meta.title||file.name.replace(/\.[^.]+$/,''),artist:meta.artist||'',cover:picture,lyrics:meta.lyrics||'',fingerprint});t.duration=duration;if(!pref().trackId)pref().trackId=t.id;if(t.id===trackId&&!audio.getAttribute('src'))await load(t);persist()}catch(error){if(mediaId)try{await media('delete',mediaId)}catch{}errors.push(file.name+'：'+error.message)}finally{if(temp)URL.revokeObjectURL(temp)}}
 if(same(identity)&&!trackId&&pref().trackId){await load(C.track(rt.state,userId,pref().trackId));tab='library'}
 }finally{importing=false;if(visible())renderPage();if(errors.length)fail(Error(errors.join('\n')))}
}
async function fetchTrackLyrics(t,identity={...who()}){
 if(!same(identity)||t.lyrics||lyricsRequests.has(t.id))return;
 const controller=new AbortController(),snapshot={title:t.title,artist:t.artist,duration:t.duration,lyrics:t.lyrics};lyricsRequests.set(t.id,controller);t.lyricsLookup={status:'loading',at:Date.now()};if(visible())renderPage();
 try{const result=await C.findLyrics(snapshot,{fetcher:fetch,signal:controller.signal});
 if(controller.signal.aborted||!same(identity)||!tracks().includes(t)||t.title!==snapshot.title||t.artist!==snapshot.artist||t.lyrics!==snapshot.lyrics)return;
 if(result?.lyrics){lyricsChoices.delete(t.id);t.lyrics=result.lyrics;t.lyricsSource={name:result.source,url:result.sourceUrl,recordId:result.recordId};t.lyricsLookup={status:'found',at:Date.now()}}
 else{if(result?.candidates?.length)lyricsChoices.set(t.id,result.candidates);t.lyricsLookup={status:result?.instrumental?'instrumental':result?.candidates?.length?'choose':'not-found',at:Date.now()}}persist();
 }catch(error){if(controller.signal.aborted){if(t.lyricsLookup?.status==='loading')delete t.lyricsLookup;return}t.lyricsLookup={status:'failed',at:Date.now()};persist();if(same(identity)&&visible())fail(error)}
 finally{if(lyricsRequests.get(t.id)===controller)lyricsRequests.delete(t.id);if(visible()&&same(identity))renderPage()}
}
function openDialog(title,body){if(dialog?.open)dialog.close();const node=document.createElement('dialog');node.className='music-dialog';node.setAttribute('aria-label',title);node.innerHTML=`<header><h2>${esc(title)}</h2><button type="button" data-music-dialog-close aria-label="关闭">×</button></header><div class="music-dialog-body">${body}</div>`;document.body.append(node);dialog=node;node.querySelector('[data-music-dialog-close]').onclick=()=>node.close();node.addEventListener('close',()=>{node.remove();if(dialog===node)dialog=null});node.showModal();return node}
function lyricsDialog(t){
 const identity={...who()};let request=null,sequence=0;const node=openDialog('Find Lyrics',`<form data-music-lyrics-search><label>歌名<input name="title" required maxlength="160" value="${esc(C.lyricTrackTitle(t.title))}"></label><label>歌手<input name="artist" maxlength="160" placeholder="填写实际演唱者，可区分翻唱版本" value="${esc(t.artist)}"></label><button type="submit" class="music-action-primary">查找歌词</button></form><div class="music-lyric-results" data-music-lyrics-results></div>`),form=node.querySelector('form'),results=node.querySelector('[data-music-lyrics-results]');
 function apply(result,title,artist){if(!same(identity)||!tracks().includes(t)||!node.open)return;lyricsRequests.get(t.id)?.abort();if(!result.lyrics)return;t.lyrics=result.lyrics;t.lyricsSource={name:result.source,url:result.sourceUrl,recordId:result.recordId};t.lyricsLookup={status:'found',at:Date.now()};if(title)t.title=C.text(title,160);if(artist)t.artist=C.text(artist,160);lyricsChoices.delete(t.id);persist();node.close();renderPage()}
 function show(rows){results.innerHTML=rows.length?rows.map((row,index)=>`<article><div><strong>${esc(row.trackName||row.name)}</strong><small>${esc(row.artistName||'未标注歌手')} · ${format(row.duration)} · ${Math.abs(Number(row.duration)-Number(t.duration))<=2&&row.syncedLyrics?'同步歌词':'文字歌词'}</small></div><button type="button" data-music-lyrics-choice="${index}" ${row.instrumental?'disabled':''}>${row.instrumental?'纯音乐':'使用这版'}</button></article>`).join(''):'<p>没有找到匹配版本，可以修改歌名和实际演唱者后重试。</p>';results.querySelectorAll('[data-music-lyrics-choice]').forEach(button=>button.onclick=()=>{const row=rows[Number(button.dataset.musicLyricsChoice)];if(row)apply(C.lyricRecord(row,{timed:!t.duration||Math.abs(Number(row.duration)-Number(t.duration))<=2}),row.trackName||row.name,row.artistName)})}
 async function search(){request?.abort();request=new AbortController();const version=++sequence,query={title:form.elements.title.value,artist:form.elements.artist.value,duration:t.duration},button=form.querySelector('button');button.disabled=true;results.innerHTML='<p>正在联网查找…</p>';
 try{const result=await C.findLyrics(query,{fetcher:fetch,signal:request.signal,candidatesOnly:true});if(version!==sequence||!node.open||!same(identity))return;if(result?.lyrics){results.innerHTML='<article><div><strong>'+esc(query.title)+'</strong><small>'+esc(query.artist)+' · 文字歌词</small></div><button type="button" data-music-lyrics-use>使用这份</button></article>';results.querySelector('[data-music-lyrics-use]').onclick=()=>apply(result,query.title,query.artist)}else show(result?.candidates||[])}catch(error){if(version===sequence&&node.open&&error.name!=='AbortError')results.innerHTML='<p role="alert">'+esc(error.message)+'</p>'}finally{if(version===sequence)button.disabled=false}}
 form.onsubmit=event=>{event.preventDefault();void search()};node.addEventListener('close',()=>request?.abort());const cached=lyricsChoices.get(t.id);if(cached?.length)show(cached);else void search();
}
function linkDialog(){const identity={...who()},node=openDialog('Add Music',`<form data-music-link-form><label>音频直链<input name="url" type="url" required placeholder="https://…/song.mp3"></label><label>歌名<input name="title" maxlength="160" required></label><label>歌手<input name="artist" maxlength="160"></label><p>请填写音频文件的直接地址。</p><button type="submit" class="music-action-primary">添加到曲库</button></form>`);node.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;try{const src=C.url(form.elements.url.value),duration=await probe(src);if(!same(identity)||!node.open)return;const t=C.add(rt.state,identity.userId,{kind:'url',url:src,duration,title:form.elements.title.value,artist:form.elements.artist.value});persist();node.close();void fetchTrackLyrics(t,identity);if(!trackId)await load(t);renderPage()}catch(error){fail(error)}finally{button.disabled=false}}}
function editDialog(t){const identity={...who()};let picture=t.cover,reading=false;const node=openDialog('Song Details',`<form data-music-edit-form><label>歌名<input name="title" required maxlength="160" value="${esc(t.title)}"></label><label>歌手<input name="artist" maxlength="160" value="${esc(t.artist)}"></label>${filePicker('cover','歌曲封面','image/jpeg,image/png,image/webp','JPG / PNG / WebP · 2 MB 以内')}${filePicker('lyrics','导入歌词','.lrc,.txt,text/plain','LRC / TXT · 支持同步歌词')}<label>歌词<textarea name="lyrics" rows="8" maxlength="120000" placeholder="粘贴 LRC 时间轴歌词或纯文字歌词">${esc(t.lyrics)}</textarea></label><div class="music-dialog-actions"><button type="submit" class="music-action-primary">保存歌曲资料</button><button type="button" class="music-action-delete" data-music-remove>删除歌曲</button></div></form>`),form=node.querySelector('form');
 node.querySelector('[data-music-cover-file]').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024){fail(Error('请选择2MB以内的 JPG、PNG 或 WebP 封面'));return}reading=true;try{picture=await dataUrl(file);node.querySelector('[data-music-cover-name]').textContent=file.name}catch(error){fail(error)}finally{reading=false}};node.querySelector('[data-music-cover-remove]').onclick=()=>{picture='';node.querySelector('[data-music-cover-file]').value='';node.querySelector('[data-music-cover-name]').textContent='JPG / PNG / WebP · 2 MB 以内'};
 node.querySelector('[data-music-lyrics-file]').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(file.size>256000){fail(Error('歌词文件不能超过256KB'));return}reading=true;try{form.elements.lyrics.value=(await file.text()).slice(0,120000);node.querySelector('[data-music-lyrics-name]').textContent=file.name}catch(error){fail(error)}finally{reading=false}};
 form.onsubmit=event=>{event.preventDefault();if(reading){fail(Error('文件还在读取，请稍后保存'));return}if(!same(identity)||!tracks().includes(t)){node.close();return}lyricsRequests.get(t.id)?.abort();if(t.lyrics!==C.text(form.elements.lyrics.value,120000))delete t.lyricsSource;delete t.lyricsLookup;Object.assign(t,{title:C.text(form.elements.title.value,160),artist:C.text(form.elements.artist.value,160),lyrics:C.text(form.elements.lyrics.value,120000),cover:picture});persist();mediaSession();node.close();renderPage();syncMini()};
 node.querySelector('[data-music-remove]').onclick=async()=>{if(!same(identity))return;lyricsRequests.get(t.id)?.abort();try{if(t.kind==='local')await media('delete',t.mediaId);if(same(identity)&&trackId===t.id){savePosition();loadedTrackId='';++epoch;audio.pause();audio.removeAttribute('src');audio.load();if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=''}trackId='';const s=together();if(s?.active)C.end(s)}music().tracks=music().tracks.filter(x=>x!==t);const settings=music().preferences[identity.userId];if(settings?.trackId===t.id)delete settings.trackId;if(settings?.positions)delete settings.positions[t.id];persist();node.close();if(same(identity))renderPage();syncMini()}catch(error){fail(error)}};
}
async function respond(action,userText=''){const identity={...who()},t=current(),s=together();if(!identity.roleId||!t||!s||pending)return;if(action!=='invite'&&!s.active)return;const version=epoch,request=++requestSerial,position=audio?.currentTime||0;pending=true;
 if(userText)C.append(s,{mine:true,text:userText,trackId:t.id,position});persist();renderPage();
 try{const context=rt.context(identity),prompt=C.prompt(action,context,t,position,s,tracks()),result=C.parse(await rt.request(prompt),action==='invite');if(version!==epoch||!same(identity)||!tracks().includes(t))return;
 delete s.failedRequest;if(action==='invite'){s.active=result.accepted;if(s.active)C.begin(s,t)}const suggestion=result.suggestion&&(result.suggestion.type==='repeat'||(result.suggestion.type==='next'&&C.next(tracks(),trackId,pref().mode))||(result.suggestion.type==='track'&&tracks().some(x=>x.id===result.suggestion.trackId)))?{...result.suggestion,fromTrackId:t.id,resolved:false}:null;C.append(s,{mine:false,text:result.text,trackId:t.id,position,suggestion:action==='invite'?null:suggestion});persist();
 }catch(error){if(version===epoch&&same(identity)){s.failedRequest={action,trackId:t.id};persist();fail(error)}}finally{if(request===requestSerial)pending=false;if(visible())renderPage();syncMini()}
}
async function acceptSuggestion(messageId){const s=together(),m=s?.thread.find(x=>x.id===messageId),suggestion=m?.suggestion;if(!s?.active||!suggestion||suggestion.resolved)return;if(suggestion.fromTrackId!==trackId){suggestion.resolved=true;persist();renderPage();return;}suggestion.resolved=true;persist();if(suggestion.type==='repeat'){audio.currentTime=0;await play()}else if(suggestion.type==='next')await step(1);else{const t=tracks().find(x=>x.id===suggestion.trackId);if(t)await load(t,true)}renderPage()}
function endDialog(){const node=openDialog('Together',`<p class="music-end-caption">结束这次一起听</p><div class="music-end-options"><button type="button" data-music-end-keep><span>结束陪伴，继续播放</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 10h12m-5-5 5 5-5 5"/></svg></button><button type="button" class="music-action-primary" data-music-end-pause><span>结束并暂停</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M7 5v10M13 5v10"/></svg></button></div>`);for(const [selector,pause]of [['[data-music-end-keep]',false],['[data-music-end-pause]',true]])node.querySelector(selector).onclick=()=>{++epoch;++requestSerial;pending=false;const s=together();if(s)C.end(s);if(pause)audio.pause();savePosition();persist();node.close();renderPage();syncMini()}}
function historyDialog(){const s=together(),i=who();const node=openDialog('Our Music',`<div class="music-history">${s?.runs.length?s.runs.slice().reverse().map(run=>`<article><h3>${esc(run.title)}</h3><small>${esc(new Date(run.startedAt).toLocaleString('zh-CN'))} · ${run.endedAt?'已结束':'正在一起听'}</small><details><summary>查看这次交流</summary>${run.messages.length?run.messages.map(m=>`<p><small>${esc(m.mine?i.userName:i.roleName)}</small>${esc(m.text)}</p>`).join(''):'<p>这次没有留下聊天文字。</p>'}</details><button type="button" data-music-remember="${esc(run.id)}">${run.remembered?'更新共同记忆':'保存为共同记忆'}</button></article>`).join(''):'<p>邀请 TA 一起听后，会在这里留下共同记录。</p>'}</div>`);node.querySelectorAll('[data-music-remember]').forEach(button=>button.onclick=()=>{const run=s.runs.find(x=>x.id===button.dataset.musicRemember);if(!run)return;try{rt.remember({...i},run);run.remembered=true;persist();button.textContent='更新共同记忆'}catch(error){fail(error)}})}
function sync(){if(!rt)return;resolveRoleInvites();if(!sameScope()){for(const request of lyricsRequests.values())request.abort();if(trackId){++epoch;++requestSerial;pending=false;savePosition();loadedTrackId='';audio?.pause();audio?.removeAttribute('src');audio?.load();if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=''}trackId='';try{if(navigator.mediaSession){navigator.mediaSession.metadata=null;navigator.mediaSession.playbackState='none'}}catch{}}if(mini)mini.hidden=true;return}syncMini()}
function acceptRoleInvite(song){if(!song?.id||!song.playUrl||!rt)return;const existing=tracks().find(item=>item.platform==='netease'&&item.platformId===String(song.id));const t=existing||C.add(rt.state,owner(),{kind:'url',url:song.playUrl,title:song.name,artist:song.artist,album:song.album,cover:song.cover,lyrics:song.lyrics,lyricsSource:song.lyrics?{name:song.lyricSource||'网易云音乐',url:'https://music.163.com'}:null,duration:song.duration,platform:'netease',platformId:String(song.id)});cloudState().songs||={};cloudState().songs[String(song.id)]=song;const s=together();if(s){s.active=true;C.begin(s,t)}pref().trackId=t.id;tab='player';persist();rt.open();queueMicrotask(()=>{if(!sameScope())return;void load(t,true)})}
function mount(runtime){const previousScope=activeScope;rt=runtime;C.normalize(rt.state);const i=who();if(!i?.userId){rt.content.innerHTML='<section class="music-empty"><p>请先选择一个用户，再打开一起听。</p></section>';return}activeScope=[i.userId,i.roleId||''].join(':');initAudio();if(previousScope&&previousScope!==activeScope){++epoch;++requestSerial;pending=false;savePosition();loadedTrackId='';audio.pause();audio.removeAttribute('src');audio.load();if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=''}trackId='';if(dialog?.open)dialog.close()}boundUserId=i.userId;if(!tracks().some(x=>x.id===trackId))trackId='';audio.volume=pref().volume??1;tab=tracks().length?'player':'library';renderPage();const saved=tracks().find(x=>x.id===pref().trackId);if(!trackId&&saved)void load(saved);syncMini();persist();void restoreCloud()}
window.IrisMusic={render:mount,sync,acceptRoleInvite,close(){savePosition();if(dialog?.open)dialog.close();syncMini()}};
})();
